# Generated by the offline template designer, not an LLM.
TILE = 14

def kernel(rows, cols, load_w, load_x):
    out = [0] * rows
    for start in range(0, rows, TILE):
        stop = min(start + TILE, rows)
        accum = [0] * (stop - start)
        for k in range(cols):
            value = load_x(k)
            for i in range(start, stop):
                accum[i - start] += load_w(i, k) * value
        for i in range(start, stop):
            out[i] = accum[i - start]
    return out
